links = {'A': ['B', 'C'], 'B': ['A', 'D'], 'C': ['A', 'E'], 'D': ['B', 'F'], 'E': ['C', 'F'], 'F': ['D', 'E', 'G'], 'G': ['F']}
seen, frontier, rounds = {'A'}, {'A'}, 0
while len(seen) < len(links):
    frontier = {n for f in frontier for n in links[f]} - seen
    seen |= frontier; rounds += 1
result = rounds

LightningNetwork:
channels = {('Alice', 'Bob'), ('Bob', 'Carol'), ('Carol', 'Dave')}
nbr = {}
for x, y in channels: nbr.setdefault(x, []).append(y); nbr.setdefault(y, []).append(x)
path, frontier = {'Alice': ['Alice']}, ['Alice']
while 'Dave' not in path:
    nxt = []
    for x in frontier:
        for y in nbr[x]:
            if y not in path: path[y] = path[x] + [y]; nxt.append(y)
    frontier = nxt
result = (path['Dave'], len(path['Dave']) - 1, ('Alice', 'Dave') in channels)
